<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\DriverService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('CARRIER_DRIVER_VIEW');$id=(int)($_GET['id']??0);$errors=[];$d=DriverService::findOwn($id);if(!$d){http_response_code(404);exit('Driver not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{$action=(string)($_POST['action']??'');if($action==='regenerate'){$r=DriverService::regenerateInvite($id,(int)Auth::user()['id']);$_SESSION['driver_setup_link']=Url::to('auth/setup-password.php?token='.urlencode($r['token']));$_SESSION['driver_setup_expires']=$r['expires_at'];header('Location: '.Url::to('carrier/drivers/view.php?id='.$id.'&link=1'));exit;}if($action==='assign'){DriverService::assignTruck($id,(int)$_POST['truck_id'],(int)Auth::user()['id']);header('Location: '.Url::to('carrier/drivers/view.php?id='.$id.'&assigned=1'));exit;}throw new RuntimeException('Unknown Driver action.');}catch(RuntimeException$e){$errors[]=$e->getMessage();}}$link=$_SESSION['driver_setup_link']??null;$expires=$_SESSION['driver_setup_expires']??null;unset($_SESSION['driver_setup_link'],$_SESSION['driver_setup_expires']);$trucks=Auth::can('CARRIER_DRIVER_ASSIGN_TRUCK')?DriverService::assignableTrucks($id):[];$pageTitle='Driver '.$d['display_name'];require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1><?=h($d['display_name'])?></h1><p><?=h($d['email'])?></p></div><span class="badge"><?=h(ucfirst($d['verification_status']))?></span></div><?php if($link):?><div class="success"><strong>One-time Driver setup link — copy it now:</strong><br><code><?=h($link)?></code><br>Expires UTC: <?=h($expires)?></div><?php endif;if(isset($_GET['assigned'])):?><div class="success">Driver linked to the verified truck. No load assignment was created.</div><?php endif;foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;if($d['case_status']==='rejected'):?><div class="error"><strong>Operations rejected verification.</strong><br><?=nl2br(h($d['findings']))?></div><?php elseif(!$d['setup_used_at']):?><div class="notice">Password setup is pending. Operations approval is blocked until it is completed.</div><?php elseif($d['case_status']==='pending'):?><div class="notice">Password setup completed; Operations verification is pending.</div><?php elseif($d['engagement_status']==='carrier_approved'):?><div class="notice">Driver is verified. Link one of your verified trucks below.</div><?php endif;?><div class="grid"><div class="card"><h3>Identity</h3><p><?=h($d['identity_type'].' · '.$d['identity_number'].' · '.$d['identity_country'])?></p></div><div class="card"><h3>Licence</h3><p><?=h($d['licence_number'].' · '.$d['licence_country'])?></p><p><?=h($d['licence_categories'].' · expires '.$d['licence_expiry'])?></p></div><div class="card"><h3>Medical</h3><p><?=h($d['medical_certificate_number'].' · '.$d['medical_result'])?></p><p>Expires <?=h($d['medical_expiry'])?></p></div></div><?php if(!$d['setup_used_at']):?><form method="post" class="card" style="margin-top:18px"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="regenerate"><p>Generating a new link invalidates the previous link.</p><button class="button secondary">Generate new 24-hour setup link</button></form><?php endif;if($d['verification_status']==='verified'&&$d['engagement_status']==='carrier_approved'):?><form method="post" class="card" style="margin-top:18px"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="assign"><div class="field"><label>Verified truck</label><select name="truck_id" required><option value="">Choose</option><?php foreach($trucks as$t):?><option value="<?=h($t['truck_id'])?>"><?=h($t['registration_number'].' · '.$t['make_name'].' '.$t['model_name'])?></option><?php endforeach;?></select></div><button class="button" style="margin-top:12px" <?=!$trucks?'disabled':''?>>Link Driver to truck</button></form><?php elseif($d['truck_id']):?><div class="card" style="margin-top:18px"><h3>Truck link</h3><p><?=h($d['registration_number'])?></p><p class="muted">This is a Carrier resource link, not a load or transport assignment.</p></div><?php endif;?><?php require BASE_PATH.'/app/Views/layout/footer.php';
